package com.bank.activity;

import java.util.*;
import java.util.concurrent.ConcurrentMap;
import java.util.logging.*;
import java.util.stream.*;

public class ActivityDemo {
    private static final Logger log = Logger.getLogger("Activity");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // 90,000 transactions across 3 accounts → 30,000 each
        List<Txn> txns = IntStream.range(0, 90_000)
            .mapToObj(i -> new Txn("ACC-" + (i % 3), i))
            .collect(Collectors.toList());
        ActivityService service = new ActivityService();

        ConcurrentMap<String, Long> counts = service.countByAccountParallel(txns);
        counts.forEach((acct, n) -> log.info(() -> acct + " txn count = " + n));
    }
}

// ─── Would be in model/Txn.java ───
record Txn(String accountId, int seq) {}

// ─── Would be in service/ActivityService.java ───
class ActivityService {
    // parallel grouping into ONE shared ConcurrentMap — no per-thread merge
    ConcurrentMap<String, Long> countByAccountParallel(List<Txn> txns) {
        return txns.parallelStream().collect(
            java.util.stream.Collectors.groupingByConcurrent(
                Txn::accountId,
                java.util.stream.Collectors.counting()));
    }
}
